        let bv = b.get(i).copied().unwrap_or(0);
        let sum = av + bv + carry;
        result.push(sum % 10);
        carry = sum / 10;
        i += 1;
    }

    if carry != 0 {
        result.push(carry);
    }

    result.iter().rev().map(|d| (*d + 48) as char).collect()
}
